import tempfile
import time
import warnings
warnings.filterwarnings('ignore')
from testthat import *
def caught(fn):
    try:
        fn()
        return ''
    except Exception as exc:
        return str(exc)
def one():
    def f():
        print("hi", end="")
        return 1
    return expect_output(f, "hi")
value = one()
